  if (root === 'tracks' && action && m === 'GET') { const rows = await tracks(c, 'AND t.slug=$1', [action], 1, 0); if (!rows[0]) throw new ApiError(404, 'Track not found.'); const sql=await database(c.env),t:any=rows[0]; const [links,lyrics,related,more]=await Promise.all([sql.query(`SELECT provider,label,url FROM entity_links WHERE entity_kind='track' AND entity_id=$1 ORDER BY position`,[t.id]),sql.query(`SELECT body,kind FROM lyrics WHERE track_id=$1`,[t.id]),tracks(c,'AND t.artist_id=$1 AND t.id<>$2',[t.artist.id,t.id],6,0),tracks(c,'AND t.artist_id=$1 AND t.id<>$2',[t.artist.id,t.id],6,0)]); return json({track:{...t,links,lyrics:lyrics[0]??null},related,moreFromArtist:more}); }
  if (root === 'tracks' && action && id === 'play' && m === 'POST') { const sql=await database(c.env); await sql.query(`UPDATE tracks SET play_count=play_count+1 WHERE id=$1 AND status='published'`,[action]); const identity=await session(c); if(identity) await sql.query(`INSERT INTO play_history(id,user_id,track_id) VALUES($1,$2,$3)`,[crypto.randomUUID(),identity.id,action]); await sql.query(`INSERT INTO play_events(id,track_id) VALUES($1,$2)`,[crypto.randomUUID(),action]); return json({ok:true}); }
  if (root === 'artists' && action && m === 'GET') { const sql=await database(c.env); const a:any[] = await sql.query(`SELECT id,slug,name,bio,image_url,location,source_type,created_at FROM artists WHERE slug=$1 AND status IN ('published','unlisted')`,[action]); if(!a[0])throw new ApiError(404,'Artist not found.'); const [links,genres,albums]=await Promise.all([sql.query(`SELECT provider,label,url FROM entity_links WHERE entity_kind='artist' AND entity_id=$1 ORDER BY position`,[a[0].id]),sql.query(`SELECT DISTINCT g.id,g.name FROM track_genres tg JOIN genres g ON g.id=tg.genre_id JOIN tracks t ON t.id=tg.track_id WHERE t.artist_id=$1`,[a[0].id]),sql.query(`SELECT id,slug,title,type,artwork_url,released_on,description,source_type,catalog_no FROM albums WHERE artist_id=$1 AND status='published'`,[a[0].id])]); return json({artist:{id:a[0].id,slug:a[0].slug,name:a[0].name,bio:a[0].bio??null,imageUrl:a[0].image_url??null,location:a[0].location??null,sourceType:a[0].source_type,createdAt:a[0].created_at,links,genres},albums,tracks:await tracks(c,'AND t.artist_id=$1',[a[0].id],100,0)}); }
  if (root === 'albums' && action && m === 'GET') { const sql=await database(c.env); const a:any[] = await sql.query(`SELECT al.*,a.name artist_name,a.slug artist_slug FROM albums al JOIN artists a ON a.id=al.artist_id WHERE al.slug=$1 AND al.status='published'`,[action]); if(!a[0])throw new ApiError(404,'Album not found.'); const links=await sql.query(`SELECT provider,label,url FROM entity_links WHERE entity_kind='album' AND entity_id=$1 ORDER BY position`,[a[0].id]); return json({album:{id:a[0].id,slug:a[0].slug,title:a[0].title,type:a[0].type,artworkUrl:a[0].artwork_url??null,releasedOn:a[0].released_on,description:a[0].description??null,sourceType:a[0].source_type,catalogNo:a[0].catalog_no??null,artist:{name:a[0].artist_name,slug:a[0].artist_slug},links},tracks:await tracks(c,'AND t.album_id=$1',[a[0].id],100,0)}); }
  if ((root === 'tracks' || root === 'artists' || root === 'albums') && m === 'GET') { const {limit,offset}=pagination(c.request); if (root==='tracks') return json({tracks:await tracks(c,'',[],limit,offset),limit,offset}); const sql=await database(c.env); if(root==='artists') return json({artists:await sql.query(`SELECT id,slug,name,bio,image_url "imageUrl",location,source_type "sourceType" FROM artists WHERE status IN ('published','unlisted') ORDER BY name LIMIT $1 OFFSET $2`,[limit,offset])}); return json({albums:await sql.query(`SELECT al.id,al.slug,al.title,al.type,al.artwork_url "artworkUrl",al.released_on "releasedOn",al.description,al.source_type "sourceType",a.name artist_name,a.slug artist_slug FROM albums al JOIN artists a ON a.id=al.artist_id WHERE al.status IN ('published','unlisted') ORDER BY al.released_on DESC NULLS LAST LIMIT $1 OFFSET $2`,[limit,offset])}); }
  if ((root === 'genres' || root === 'tags') && m === 'GET') { const sql=await database(c.env); const table=root==='genres'?'genres':'tags'; const join=root==='genres'?'track_genres':'track_tags'; const rows=await sql.query(`SELECT x.id,x.name,count(j.track_id)::text track_count FROM ${table} x LEFT JOIN ${join} j ON j.${root==='genres'?'genre_id':'tag_id'}=x.id GROUP BY x.id ORDER BY track_count DESC,x.name`); return json({[root]:rows.map((x:any)=>({id:x.id,name:x.name,trackCount:Number(x.track_count)}))}); }
